package io.github.zancrow321.jadm.engine.data;

import com.google.gson.JsonElement;
import com.google.gson.JsonParser;

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.random.RandomGenerator;

/**
 * The alternate artworks players can pull: other printings of a card with a picture of their own, generated by
 * {@code tools/carddata/build_alt_arts.py}. An alt art has its own passcode but plays as the original, counts as it
 * in decks and the banlist, and keeps its artwork wherever the card is shown.
 *
 * @param byOriginal the original's passcode to its alternate artworks' (never empty)
 */
public record AltArts(Map<Integer, List<Integer>> byOriginal) {
    public static final String RESOURCE = "/jadm/alt_arts.json";
    /** The chance a pulled card that has alternate artworks comes as one of them, unless a server sets its own. */
    public static final double DEFAULT_CHANCE = 0.2;

    public AltArts {
        Map<Integer, List<Integer>> copy = new LinkedHashMap<>();
        byOriginal.forEach((k, v) -> copy.put(k, List.copyOf(v)));
        byOriginal = Collections.unmodifiableMap(copy);
    }

    /** @return the alternate artworks of a card's original that can be pulled; empty if there are none */
    public List<Integer> of(CardDatabase cards, int code) {
        return byOriginal.getOrDefault(cards.original(code), List.of());
    }

    /**
     * Which artwork of a card this is: 1 for the original, 2 and up for the alternate artworks in passcode order, or
     * 0 for an alternate artwork that isn't handed out.
     */
    public int number(CardDatabase cards, int code) {
        int original = cards.original(code);
        if (original == code) {
            return 1;
        }
        int i = byOriginal.getOrDefault(original, List.of()).indexOf(code);
        return i < 0 ? 0 : i + 2;
    }

    /** How many artworks a card has that can be pulled, the original's included. */
    public int count(CardDatabase cards, int code) {
        return 1 + of(cards, code).size();
    }

    /**
     * A pulled card: with {@code chance}, if it has any, one of the card's other artworks (each as likely), otherwise
     * the card as it is.
     */
    public int roll(CardDatabase cards, int code, double chance, RandomGenerator random) {
        int original = cards.original(code);
        List<Integer> alts = byOriginal.get(original);
        if (alts == null || chance <= 0 || random.nextDouble() >= chance) {
            return code;
        }
        List<Integer> others = new ArrayList<>(alts.size() + 1);
        if (original != code) {
            others.add(original);
        }
        alts.stream().filter(c -> c != code).forEach(others::add);
        return others.isEmpty() ? code : others.get(random.nextInt(others.size()));
    }

    public static AltArts loadBundled() {
        try (InputStream in = AltArts.class.getResourceAsStream(RESOURCE)) {
            if (in == null) {
                throw new IllegalStateException("Missing " + RESOURCE);
            }
            Map<Integer, List<Integer>> byOriginal = new LinkedHashMap<>();
            JsonParser.parseReader(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject().entrySet()
                    .forEach(e -> {
                        List<Integer> alts = new ArrayList<>();
                        for (JsonElement c : e.getValue().getAsJsonArray()) {
                            alts.add(c.getAsInt());
                        }
                        if (!alts.isEmpty()) {
                            byOriginal.put(Integer.parseInt(e.getKey()), alts);
                        }
                    });
            return new AltArts(byOriginal);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
